// Fixed std-only CPU children; no arbitrary executable or native library runs.
#include "bounded_launcher.hpp"
#include <filesystem>
#include <iostream>
using namespace hs::n1chain;
namespace fs=std::filesystem;
static unsigned groups=0;
static void ck(bool b,const char*w){if(!b)throw Blocked(w);}
template<class F>static void reject(F f){bool rejected=false;try{f();}catch(const std::exception&){rejected=true;}ck(rejected,"expected bounded launcher rejection");}
static BoundedLaunchSpec spec(double seconds=2){BoundedLaunchSpec s;s.controller={::getpid(),controller_start_ticks(::getpid()),controller_boot_id()};s.deadline_wall=launch_clock(CLOCK_REALTIME)+seconds;s.deadline_mono=launch_clock(CLOCK_MONOTONIC)+seconds;return s;}
struct Logs{FD out,err;std::string a,b;};
static Logs logs(const std::string&root,const std::string&name){const auto a=root+"/"+name+".out",b=root+"/"+name+".err";FD out(::open(a.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW,0600)),err(::open(b.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW,0600));checked(out.n,"fresh mock output");checked(err.n,"fresh mock error");return{std::move(out),std::move(err),a,b};}
static void hang(){for(;;)::pause();}
struct DenySpy:BudgetHooks{
 unsigned calls=0;
 void before_backend_init(const std::string&)override{calls++;}void before_model_load(const std::string&)override{calls++;}void before_context(const std::string&)override{calls++;}void before_placement(const std::string&)override{calls++;}void before_request(const std::string&)override{calls++;}void before_decode(const std::string&,size_t)override{calls++;}void before_mutation(const std::string&,const std::string&)override{calls++;}void finish_request(const std::string&,const std::string&)override{calls++;}void poison(const std::string&)noexcept override{calls++;}
};
int main(int argc,char**argv){try{
 ck(argc==3&&std::string(argv[1])=="--cpu-only-launcher-test","explicit CPU-only launcher fixture mode required");const std::string root=argv[2];ck(root[0]=='/'&&root.size()<80,"fresh absolute CPU fixture root");checked(::mkdir(root.c_str(),0700),"fresh launcher mock directory");checked(::prctl(PR_SET_CHILD_SUBREAPER,1),"own mock subtree reaper");
 auto test=[&](const char*name,const auto&fn){fn();groups++;std::cout<<"PASS "<<name<<'\n';};
 test("permanent native gate denies before account or fork",[]{ProductionGate g;DenySpy b;BoundedLaunchSpec empty;reject([&]{(void)guarded_native_launch(g,b,empty);});ck(b.calls==0,"no native accounting side effect before deny");});
 test("fixed CPU child normal exit is reaped",[]{auto s=spec();const auto r=launch_detail::supervise_owned(s,[]{});ck(r.status=="OWNED_CHILD_EXITED"&&r.exit_confirmed&&WIFEXITED(r.wait_status)&&WEXITSTATUS(r.wait_status)==0&&!r.native_authority,"owned CPU exit");});
 test("absolute deadline sends SIGKILL only through owned pidfd",[]{const auto began=launch_clock(CLOCK_MONOTONIC);auto s=spec(.15);const auto r=launch_detail::supervise_owned(s,hang);ck(r.status=="DEADLINE_STOP_SENT"&&r.stop_signal_delivered&&r.exit_confirmed&&WIFSIGNALED(r.wait_status)&&WTERMSIG(r.wait_status)==SIGKILL,"owned deadline stop");ck(launch_clock(CLOCK_MONOTONIC)-began<1.5,"bounded CPU stop response");});
 test("expired wall lease rejects before child action",[]{auto s=spec();s.deadline_wall=launch_clock(CLOCK_REALTIME)-1;reject([&]{(void)launch_detail::supervise_owned(s,hang);});});
 test("expired monotonic lease rejects",[]{auto s=spec();s.deadline_mono=launch_clock(CLOCK_MONOTONIC)-1;reject([&]{(void)launch_detail::supervise_owned(s,hang);});});
 test("lease exceeding five hours rejects",[]{auto s=spec(18001);reject([&]{(void)launch_detail::supervise_owned(s,hang);});});
 test("zombie controller is owner loss even before PID is reaped",[]{const auto owner=::fork();checked(owner,"fork fixed CPU owner");if(owner==0){::poll(nullptr,0,100);::_exit(0);}auto s=spec();s.controller={owner,controller_start_ticks(owner),controller_boot_id()};const auto r=launch_detail::supervise_owned(s,hang);int status=0;checked(::waitpid(owner,&status,0),"reap own fake controller");ck(r.status=="CONTROLLER_LOST_STOP_SENT"&&r.stop_signal_delivered&&r.exit_confirmed,"dead owner stops owned child");});
 test("kernel parent-death kills owned CPU descendant",[]{int p[2];checked(::pipe2(p,O_CLOEXEC),"owned descendant identity pipe");FD read(p[0]),write(p[1]);const auto supervisor=::fork();checked(supervisor,"fork own CPU supervisor");if(supervisor==0){read=FD{};try{auto s=spec(3);(void)launch_detail::supervise_owned(s,[&]{const auto child=::getpid();if(::write(write.n,&child,sizeof child)!=sizeof child)::_exit(141);hang();});}catch(...){::_exit(142);}::_exit(143);}write=FD{};pid_t descendant=-1;ck(::read(read.n,&descendant,sizeof descendant)==sizeof descendant&&descendant>0,"owned descendant announced");auto descendant_fd=launch_detail::child_pidfd(descendant),supervisor_fd=launch_detail::child_pidfd(supervisor);ck(launch_detail::kill_owned(supervisor_fd.n),"stop own CPU supervisor");int status=0;checked(::waitpid(supervisor,&status,0),"reap owned supervisor");pollfd ready{descendant_fd.n,POLLIN,0};const auto n=::poll(&ready,1,1500);if(n<=0){(void)launch_detail::kill_owned(descendant_fd.n);int cleanup=0;::waitpid(descendant,&cleanup,0);throw Blocked("parent-death did not terminate owned CPU child");}checked(::waitpid(descendant,&status,0),"reap reparented own descendant");ck(WIFSIGNALED(status)&&WTERMSIG(status)==SIGKILL,"kernel parent-death signal");});
 test("parent drains complete stdout and stderr within frozen caps",[&]{auto l=logs(root,"normal");auto s=spec();s.stdout_fd=l.out.n;s.stderr_fd=l.err.n;s.per_log_bytes=16;const auto r=launch_detail::supervise_owned(s,[]{if(::write(STDOUT_FILENO,"abcd",4)!=4||::write(STDERR_FILENO,"efgh",4)!=4)::_exit(151);});ck(r.status=="OWNED_CHILD_EXITED"&&r.exit_confirmed&&r.stdout_complete&&r.stderr_complete&&!r.output_partial&&r.stdout_bytes==4&&r.stderr_bytes==4&&fs::file_size(l.a)==4&&fs::file_size(l.b)==4,"complete bounded logs");});
 for(bool error:{false,true})test(error?"stderr overflow preserves capped prefix and stops":"stdout overflow preserves capped prefix and stops",[&,error]{auto l=logs(root,error?"errlimit":"outlimit");auto s=spec();s.stdout_fd=l.out.n;s.stderr_fd=l.err.n;s.per_log_bytes=16;const auto r=launch_detail::supervise_owned(s,[=]{char bytes[4096];std::memset(bytes,'x',sizeof bytes);if(::write(error?STDERR_FILENO:STDOUT_FILENO,bytes,sizeof bytes)<0)::_exit(152);hang();});ck(r.status=="OUTPUT_LIMIT_STOP_SENT"&&r.exit_confirmed&&r.output_partial&&!r.stdout_complete&&!r.stderr_complete&&(error?r.stderr_bytes:r.stdout_bytes)==16&&fs::file_size(error?l.b:l.a)==16&&fs::file_size(error?l.a:l.b)==0,"quota prefix never exceeds hard file cap");});
 test("partial parent log write stops without retry",[&]{auto l=logs(root,"short");auto s=spec();s.stdout_fd=l.out.n;s.stderr_fd=l.err.n;s.per_log_bytes=16;BoundedLogIO io;unsigned writes=0;io.write=[&](int f,const void*p,size_t n){writes++;return::write(f,p,n/2);};const auto r=launch_detail::supervise_owned(s,[]{::write(STDOUT_FILENO,"abcdefgh",8);hang();},io);ck(r.status=="OUTPUT_WRITE_FAILURE_STOP_SENT"&&r.exit_confirmed&&r.output_partial&&r.stdout_bytes==4&&writes==1&&fs::file_size(l.a)==4,"partial log retained without retry");});
 test("ENOSPC parent log failure stops owned child",[&]{auto l=logs(root,"full");auto s=spec();s.stdout_fd=l.out.n;s.stderr_fd=l.err.n;s.per_log_bytes=16;BoundedLogIO io;io.write=[](int,const void*,size_t)->ssize_t{errno=ENOSPC;return-1;};const auto r=launch_detail::supervise_owned(s,[]{::write(STDOUT_FILENO,"x",1);hang();},io);ck(r.status=="OUTPUT_WRITE_FAILURE_STOP_SENT"&&r.exit_confirmed&&fs::file_size(l.a)==0,"disk full log stop");});
 test("fsync failure remains failure after child exits0",[&]{auto l=logs(root,"sync");auto s=spec();s.stdout_fd=l.out.n;s.stderr_fd=l.err.n;s.per_log_bytes=16;BoundedLogIO io;io.sync=[](int){errno=EIO;return-1;};const auto r=launch_detail::supervise_owned(s,[]{::write(STDOUT_FILENO,"x",1);},io);ck(r.status=="OUTPUT_FSYNC_FAILURE"&&r.exit_confirmed&&r.output_partial&&!r.stdout_complete&&!r.stderr_complete&&r.stdout_bytes==1&&WIFEXITED(r.wait_status)&&WEXITSTATUS(r.wait_status)==0,"exit0 cannot erase parent write failure");});
 test("reused log file rejects before child",[&]{auto l=logs(root,"reuse");ck(::write(l.out.n,"x",1)==1,"initial retained log");auto s=spec();s.stdout_fd=l.out.n;s.stderr_fd=l.err.n;s.per_log_bytes=16;reject([&]{(void)launch_detail::supervise_owned(s,hang);});ck(fs::file_size(l.a)==1,"old log untouched");});
 test("same-inode stdout and stderr reject",[&]{auto l=logs(root,"same");auto s=spec();s.stdout_fd=l.out.n;s.stderr_fd=l.out.n;s.per_log_bytes=16;reject([&]{(void)launch_detail::supervise_owned(s,hang);});});
 test("nonzero file offset cannot create sparse quota bypass",[&]{auto l=logs(root,"offset");ck(::lseek(l.out.n,100,SEEK_SET)==100,"mock offset");auto s=spec();s.stdout_fd=l.out.n;s.stderr_fd=l.err.n;s.per_log_bytes=16;reject([&]{(void)launch_detail::supervise_owned(s,hang);});ck(fs::file_size(l.a)==0,"no sparse data side effect");});
 test("per-stream cap above twelve MiB rejects",[&]{auto l=logs(root,"max");auto s=spec();s.stdout_fd=l.out.n;s.stderr_fd=l.err.n;s.per_log_bytes=12*1024*1024+1;reject([&]{(void)launch_detail::supervise_owned(s,hang);});});
 std::cout<<"{\"status\":\"CPU_ONLY_BOUNDED_LAUNCHER_PASS\",\"groups\":"<<groups<<",\"native_executables_started\":0,\"backend_model_context_placement_forward_calls\":0,\"native_authority\":false}\n";return 0;
 }catch(const std::exception&e){std::cerr<<"CPU_ONLY_BOUNDED_LAUNCHER_FAIL "<<e.what()<<'\n';return 1;}}
